alter table public.stock_transfers add column if not exists transfer_number text; alter table public.stock_transfers add column if not exists requested_by uuid references auth.users(id); alter table public.stock_transfers add column if not exists dispatched_by uuid references auth.users(id); alter table public.stock_transfers add column if not exists received_by uuid references auth.users(id); alter table public.stock_transfers add column if not exists requested_at timestamptz default now(); alter table public.stock_transfers add column if not exists dispatched_at timestamptz; alter table public.stock_transfers add column if not exists received_at timestamptz; alter table public.stock_transfers add column if not exists cancelled_at timestamptz; alter table public.stock_transfers add column if not exists notes text; update public.stock_transfers set transfer_number='TR-LEGACY-'||id::text where transfer_number is null; alter table public.stock_transfers alter column transfer_number set not null; create unique index if not exists ux_stock_transfers_business_number on public.stock_transfers(business_id,transfer_number); create table if not exists public.stock_transfer_batch_lines (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, stock_transfer_line_id uuid not null references public.stock_transfer_lines(id) on delete cascade, source_batch_id uuid not null, batch_code text not null, expiry_date date, quantity numeric(24,8) not null check(quantity>0), unit text not null, created_at timestamptz not null default now()); create index if not exists idx_v19_transfer_batches_line on public.stock_transfer_batch_lines(business_id,stock_transfer_line_id);